describe('Search Filter - Exclude Term', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should exclude a term from search results by prefixing with "-", and display only relevant results', () => {
    // Setup: Intercept the search API call
    cy.intercept('GET', '/api/search*', (req) => {
      expect(req.url).to.include('/api/search');
      expect(req.body.query).to.equal('apple');
    }).as('searchRequest');

    // Act: Perform search with excluded term
    cy.get('[data-testid="search-input"]').type('apple -red');
    cy.get('[data-testid="search-button"]').click();

    // Wait for API response
    cy.wait('@searchRequest');

    // Assert: Excluded term should not appear in results
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="result-item"]').first().should('contain', 'apple');
    cy.get('[data-testid="result-item"]').first().should('not.contain', 'red');

    // Assert: Excluded term should be displayed in the search input
    cy.get('[data-testid="search-input"]').should('contain', '-red');
  });

  it('should handle multiple excluded terms and display only relevant results', () => {
    // Setup: Intercept the search API call
    cy.intercept('GET', '/api/search*', (req) => {
      expect(req.url).to.include('/api/search');
      expect(req.body.query).to.equal('banana -yellow -ripe');
    }).as('searchRequest');

    // Act: Perform search with multiple excluded terms
    cy.get('[data-testid="search-input"]').type('banana -yellow -ripe');
    cy.get('[data-testid="search-button"]').click();

    // Wait for API response
    cy.wait('@searchRequest');

    // Assert: Excluded terms should not appear in results
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="result-item"]').first().should('contain', 'banana');
    cy.get('[data-testid="result-item"]').first().should('not.contain', 'yellow');
    cy.get('[data-testid="result-item"]').first().should('not.contain', 'ripe');

    // Assert: Excluded terms should be displayed in the search input
    cy.get('[data-testid="search-input"]').should('contain', '-yellow -ripe');
  });
});
